import java.util.Scanner;

interface Borrowable {
    boolean isAvailable();
    void borrow();
    void returnItem();
}

interface Printable {
    String getSummary();

    default void printLabel() {
        System.out.println("=== LABEL RAK ===");
        System.out.println(getSummary());
        System.out.println("=================");
    }
}

// Buat kelas Magazine yang mengimplementasikan Borrowable dan Printable. Atribut: title dan available (awalnya true). borrow(): bila tersedia, jadi tidak tersedia dan cetak "Dipinjam: <title>"; bila tidak, cetak "<title> sedang dipinjam". returnItem(): jadi tersedia dan cetak "Dikembalikan: <title>". getSummary(): "<title> [Tersedia]" atau "<title> [Dipinjam]".

public class Main {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        Magazine m = new Magazine(in.nextLine().trim());
        while (in.hasNextLine()) {
            String cmd = in.nextLine().trim();
            if (cmd.equals("selesai")) {
                break;
            } else if (cmd.equals("pinjam")) {
                m.borrow();
            } else if (cmd.equals("kembali")) {
                m.returnItem();
            } else if (cmd.equals("label")) {
                m.printLabel();
            }
        }
    }
}
